def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    out = g.copy()
    seeds = list(zip(*np.where(g == 2)))
    for (y, x) in seeds:
        out[y, x] = bg
    emit(out.copy(), "Erase the colour-2 seed cell; it will be replaced by its diagonal neighbours.")
    table = {(-1, -1): 3, (-1, 1): 6, (1, -1): 8, (1, 1): 7}
    for (y, x) in seeds:
        for (dy, dx), c in table.items():
            ny, nx = y + dy, x + dx
            if 0 <= ny < H and 0 <= nx < W:
                out[ny, nx] = c
        emit(out.copy(), f"Place diagonal neighbours of ({y},{x}): up-left 3, up-right 6, down-left 8, down-right 7 (skipping off-grid ones).")
    emit(out.copy(), "Final grid.")
    return out
